#!/usr/bin/env bash
# Turns the Swift snippets of the user-facing docs into Swift source that the test build compiles.
#
#   ./scripts/check-doc-snippets.sh            # fail if the generated files are out of date
#   ./scripts/check-doc-snippets.sh --update   # write the generated files
#
# Each ```swift fence at the start of a line becomes one function in Tests/DocSnippetsTests/<Name>Snippets.swift. The
# function takes `client: SupabaseClient`, so a snippet can use `client` without creating it.
# `swift build --build-tests` then fails when a snippet no longer compiles. Names that an app
# would define itself are in Tests/DocSnippetsTests/Prelude.swift.
#
# Put `<!-- snippet: no-compile -->` on the line before a fence to skip it: a `Package.swift`
# fragment, or SwiftUI code that is not a list of statements.
set -euo pipefail

cd "$(dirname "$0")/.."

# "<markdown file>:<generated file name>:<function name prefix>"
DOCS=(
  "README.md:READMESnippets:readme"
)
OUT_DIR=Tests/DocSnippetsTests

generate() {
  local doc=$1 prefix=$2
  awk -v doc="$doc" -v prefix="$prefix" '
    BEGIN {
      print "// Generated by scripts/check-doc-snippets.sh from " doc ". Do not edit."
      print "// swift-format-ignore-file"
      print ""
      print "import Foundation"
      print "import Supabase"
      print ""
      print "#if canImport(FoundationNetworking)"
      print "  import FoundationNetworking"
      print "#endif"
    }
    /^<!-- snippet: no-compile -->$/ { skip = 1; next }
    /^```swift$/ && !inside {
      inside = 1
      if (skip) { skipping = 1 } else {
        count++
        print ""
        print "func " prefix "Snippet" count "(client: SupabaseClient) async throws {"
      }
      skip = 0
      next
    }
    /^```$/ && inside {
      if (!skipping) print "}"
      inside = 0; skipping = 0
      next
    }
    !inside && /^[[:space:]]*```+[[:space:]]*[Ss]wift/ {
      print doc ":" NR ": write a Swift fence as ```swift at the start of the line" > "/dev/stderr"
      bad = 1
    }
    inside && !skipping {
      if ($0 ~ /^import /) next
      print ($0 == "" ? "" : "  " $0)
      next
    }
    /[^[:space:]]/ { skip = 0 }
    END { exit bad }
  ' "$doc"
}

status=0
for entry in "${DOCS[@]}"; do
  IFS=: read -r doc name prefix <<< "$entry"
  out="$OUT_DIR/$name.swift"
  generated=$(generate "$doc" "$prefix") || { status=1; continue; }
  if [[ "${1:-}" == "--update" ]]; then
    printf '%s\n' "$generated" > "$out"
  elif ! diff -q "$out" <(printf '%s\n' "$generated") >/dev/null 2>&1; then
    echo "$out is out of date with $doc. Run ./scripts/check-doc-snippets.sh --update"
    status=1
  fi
done
exit "$status"
